using namespace std;

const int INF = 1000000001;

struct Pair {
    int first, second;
};

void sort(vector<int>& arr) {
    if (arr.size() < 2) return;
    function<void(int, int)> quicksort = [&](int l, int r) {
        if (l >= r) return;
        int left = l;
        int right = r;
        int pivot = (l + r) / 2;
        swap(arr[pivot], arr[right]);
        for (int i = l; i <= r; i++) {
            if (arr[i] < arr[right]) {
                swap(arr[i], arr[left]);
                left++;
            }
        }
        swap(arr[left], arr[right]);
        quicksort(l, left - 1);
        quicksort(left + 1, r);
    };
    quicksort(0, arr.size() - 1);
}

bool check(int n) {
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s == 10;
}

void solution(istream& reader, ostream& writer) {
    int k;
    reader >> k;
    for (int i = 19; k > 0; i++) {
        if (check(i)) {
            k--;
        }
        if (k == 0) {
            writer << i << '\n';
            return;
        }
    }
}

